theorem example_2_27 [FiniteDimensional ℝ E] (z x : E) :
    SourceSubdifferential (sourceHinge z) x =
      if 1 - inner ℝ z x < 0 then {0}
      else if 1 - inner ℝ z x = 0 then
        {g | ∃ α ∈ Icc (0 : ℝ) 1, g = -(α • z)}
      else {-z}

def predict (V : Set X) (initial : V) (loss : ℕ → X → ℝ) (t : ℕ) : Option X :=
  if t = 0 then some (initial : X) else select V (fun i : Fin t => loss i.val)

theorem select_some_spec (V : Set X) (past : Fin n → X → ℝ) (p : X) (h : select V past = some p) :
    p ∈ V ∧ IsMinOn (cumulative past) V p
